// A swarm on the container's loopback, for app_checks' streaming check: a generated file made
// into a torrent, seeders that are separate libtorrent sessions on their own 127.0.0.x
// addresses with their own upload limits, and a tracker that hands the engine their addresses.
// Harness code only (tests/torrent links libtorrent); the app never includes it.
#pragma once

#include <libtorrent/add_torrent_params.hpp>
#include <libtorrent/address.hpp>
#include <libtorrent/bencode.hpp>
#include <libtorrent/create_torrent.hpp>
#include <libtorrent/ip_filter.hpp>
#include <libtorrent/session.hpp>
#include <libtorrent/session_params.hpp>
#include <libtorrent/settings_pack.hpp>
#include <libtorrent/torrent_flags.hpp>
#include <libtorrent/torrent_handle.hpp>
#include <libtorrent/torrent_info.hpp>
#include <libtorrent/torrent_status.hpp>

#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

#include <algorithm>
#include <cerrno>
#include <atomic>
#include <cstdint>
#include <cstdio>
#include <memory>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

namespace swarm {

namespace lt = libtorrent;

/// The byte at `offset` of every generated file: a cheap hash of the offset, so a reader can
/// check what it read without keeping the file.
inline unsigned char byteAt(int64_t offset) {
    uint64_t x = uint64_t(offset) * 0x9E3779B97F4A7C15ull;
    x ^= x >> 29;
    return static_cast<unsigned char>(x >> 7);
}

/// Writes `size` generated bytes to `path`.
inline bool generateFile(const std::string& path, int64_t size) {
    std::FILE* f = std::fopen(path.c_str(), "wb");
    if (!f) return false;
    std::vector<unsigned char> buf(size_t(1) << 20);
    bool ok = true;
    for (int64_t at = 0; at < size && ok; at += int64_t(buf.size())) {
        const size_t n = size_t(std::min<int64_t>(int64_t(buf.size()), size - at));
        for (size_t i = 0; i < n; ++i) buf[i] = byteAt(at + int64_t(i));
        ok = std::fwrite(buf.data(), 1, n, f) == n;
    }
    return std::fclose(f) == 0 && ok;
}

struct Torrent {
    std::string infoHash;  // v1, 40 lowercase hex
    std::shared_ptr<const lt::torrent_info> info;
};

/// A v1 torrent of the single file `dir`/`name`, with pieces of `pieceLength` bytes.
inline Torrent makeTorrent(const std::string& dir, const std::string& name, int pieceLength) {
    lt::file_storage fs;
    lt::add_files(fs, dir + "/" + name);
    lt::create_torrent ct(fs, pieceLength, lt::create_torrent::v1_only);
    lt::set_piece_hashes(ct, dir);
    std::vector<char> buf;
    lt::bencode(std::back_inserter(buf), ct.generate());
    Torrent t;
    t.info = std::make_shared<lt::torrent_info>(buf, lt::from_span);
    std::ostringstream hex;
    hex << t.info->info_hashes().v1;
    t.infoHash = hex.str();
    return t;
}

/// One peer of the swarm: how fast it sends, and which share of the pieces it has (a random
/// subset, the same every run; 1 is a seeder).
struct Peer {
    int uploadKiB = 0;
    double share = 1;
};

/// The peers of `torrent` (whose file is in `dir`), each its own session on
/// 127.0.0.(11 + i):(basePort + i). A peer with part of the pieces only uploads: it downloads
/// nothing, so the engine's peers keep the availability they started with.
class Seeders {
public:
    Seeders(const Torrent& torrent, const std::string& dir, const std::vector<Peer>& peers, int basePort) {
        const int pieces = torrent.info->num_pieces();
        uint64_t rng = 0x2545F4914F6CDD1Dull;
        for (size_t i = 0; i < peers.size(); ++i) {
            const std::string ip = "127.0.0." + std::to_string(11 + i);
            const int port = basePort + int(i);
            lt::settings_pack sp;
            sp.set_str(lt::settings_pack::listen_interfaces, ip + ":" + std::to_string(port));
            sp.set_bool(lt::settings_pack::enable_dht, false);
            sp.set_bool(lt::settings_pack::enable_lsd, false);
            sp.set_bool(lt::settings_pack::enable_upnp, false);
            sp.set_bool(lt::settings_pack::enable_natpmp, false);
            sp.set_int(lt::settings_pack::upload_rate_limit, peers[i].uploadKiB << 10);
            sp.set_int(lt::settings_pack::alert_mask, 0);
            sp.set_int(lt::settings_pack::aio_threads, 1);
            sp.set_int(lt::settings_pack::hashing_threads, 1);
            auto s = std::make_unique<lt::session>(lt::session_params(std::move(sp)));
            // the engine is on 127.0.0.1, a local peer, which no rate limit applies to by
            // default: put every address in the global class, the one upload_rate_limit governs
            lt::ip_filter f;
            f.add_rule(lt::make_address("0.0.0.0"), lt::make_address("255.255.255.255"),
                       1u << static_cast<std::uint32_t>(lt::session::global_peer_class_id));
            s->set_peer_class_filter(f);
            lt::add_torrent_params atp;
            atp.ti = std::make_shared<lt::torrent_info>(*torrent.info);
            atp.save_path = dir;
            atp.flags &= ~(lt::torrent_flags::auto_managed | lt::torrent_flags::paused);
            if (peers[i].share >= 1) {
                atp.flags |= lt::torrent_flags::seed_mode;
            } else {
                // resume data: these pieces are in, the file is there, nothing else is wanted
                atp.have_pieces.resize(pieces, false);
                for (int p = 0; p < pieces; ++p) {
                    rng ^= rng << 13;
                    rng ^= rng >> 7;
                    rng ^= rng << 17;
                    if (double(rng % 1000) < peers[i].share * 1000) atp.have_pieces.set_bit(lt::piece_index_t(p));
                }
                atp.file_priorities.assign(size_t(torrent.info->num_files()), lt::dont_download);
            }
            handles.push_back(s->add_torrent(std::move(atp)));
            sessions.push_back(std::move(s));
            endpoints.emplace_back(ip, port);
        }
    }

    /// Pieces each peer has, once their sessions have taken the torrent in.
    std::vector<int> pieceCounts() const {
        std::vector<int> n;
        for (const auto& h : handles) n.push_back(h.status(lt::status_flags_t{}).num_pieces);
        return n;
    }

    ~Seeders() {
        // closes them all at once, not one after another
        std::vector<lt::session_proxy> closing;
        for (auto& s : sessions) closing.push_back(s->abort());
        sessions.clear();
    }

    Seeders(const Seeders&) = delete;
    Seeders& operator=(const Seeders&) = delete;

    /// Payload bytes all seeders have sent: what the engine downloaded, redundant bytes included.
    int64_t uploaded() const {
        int64_t n = 0;
        for (const auto& h : handles) n += h.status(lt::status_flags_t{}).total_payload_upload;
        return n;
    }

    std::vector<std::pair<std::string, int>> endpoints;

private:
    std::vector<std::unique_ptr<lt::session>> sessions;
    std::vector<lt::torrent_handle> handles;
};

/// An HTTP tracker on 127.0.0.1:`port` that answers every announce with the same peers.
class Tracker {
public:
    Tracker(int port, const std::vector<std::pair<std::string, int>>& peers) {
        std::string compact;
        for (const auto& p : peers) {
            in_addr a{};
            inet_pton(AF_INET, p.first.c_str(), &a);
            compact.append(reinterpret_cast<const char*>(&a), 4);
            compact.push_back(char((p.second >> 8) & 0xff));
            compact.push_back(char(p.second & 0xff));
        }
        body = "d8:intervali1800e5:peers" + std::to_string(compact.size()) + ":" + compact + "e";
        fd = socket(AF_INET, SOCK_STREAM, 0);
        int one = 1;
        setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
        sockaddr_in a{};
        a.sin_family = AF_INET;
        a.sin_port = htons(uint16_t(port));
        a.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        ok = bind(fd, reinterpret_cast<sockaddr*>(&a), sizeof a) == 0 && listen(fd, 16) == 0;
        if (ok) thread = std::thread([this] { serve(); });
    }

    ~Tracker() {
        stopping = true;
        shutdown(fd, SHUT_RDWR);  // wakes accept()
        if (thread.joinable()) thread.join();
        close(fd);
    }

    Tracker(const Tracker&) = delete;
    Tracker& operator=(const Tracker&) = delete;

    bool ok = false;

private:
    void serve() {
        while (!stopping) {
            int c = accept(fd, nullptr, nullptr);
            if (c < 0) {
                if (!stopping && (errno == EINTR || errno == ECONNABORTED)) continue;
                break;  // shut down
            }
            std::string req;
            char buf[2048];
            ssize_t n;
            while (req.find("\r\n\r\n") == std::string::npos && (n = recv(c, buf, sizeof buf, 0)) > 0)
                req.append(buf, size_t(n));
            const std::string resp = "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: " +
                                     std::to_string(body.size()) + "\r\nConnection: close\r\n\r\n" + body;
            send(c, resp.data(), resp.size(), MSG_NOSIGNAL);
            close(c);
        }
    }

    int fd = -1;
    std::string body;
    std::atomic<bool> stopping{false};
    std::thread thread;
};

}  // namespace swarm
